    let bindings_contract_version = 30
    // Get the scaffolding contract version by calling the into the dylib
    let scaffolding_contract_version = ffi_api_bones_sdk_ffi_uniffi_contract_version()
    if bindings_contract_version != scaffolding_contract_version {
        return InitializationResult.contractVersionMismatch
    }
    if (uniffi_api_bones_sdk_ffi_checksum_func_api_bones_sdk_build_info() != 38064) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_api_bones_sdk_ffi_checksum_func_format_error() != 41578) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_api_bones_sdk_ffi_checksum_method_ffihandle_cancel() != 7454) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_api_bones_sdk_ffi_checksum_method_ffihandle_next() != 13950) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_api_bones_sdk_ffi_checksum_method_ffihandle_span() != 41094) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_api_bones_sdk_ffi_checksum_method_ffihost_credential() != 60461) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_api_bones_sdk_ffi_checksum_method_ffihost_anonymous() != 36152) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_api_bones_sdk_ffi_checksum_method_ffihost_unauthenticated() != 25891) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_api_bones_sdk_ffi_checksum_method_ffihost_span_start() != 39924) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_api_bones_sdk_ffi_checksum_method_ffihost_span_end() != 35788) {
        return InitializationResult.apiChecksumMismatch
